<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Certificate verification</title><style>body{font:15px Arial;background:#f5f6fa;color:#172038;display:grid;place-items:center;min-height:100vh}.box{width:min(600px,90%);background:#fff;padding:35px;border-radius:16px;box-shadow:0 10px 40px #18204015}.valid{color:#187744}.bad{color:#b43b4b}</style></head><body><div class="box">@if(!$certificate)<h1 class="bad">Certificate not found</h1><p>The supplied verification code is invalid.</p>@elseif($certificate->revoked_at)<h1 class="bad">Certificate revoked</h1><p>{{$certificate->serial_no}} was revoked on {{$certificate->revoked_at->format('d M Y')}}.</p><p>{{$certificate->revocation_reason}}</p>@else<h1 class="valid">✓ Valid certificate</h1><p><strong>{{$certificate->title}}</strong></p><p>Issued by {{$certificate->school->name}} to <strong>{{$certificate->student->full_name}}</strong>.</p><p>Serial: {{$certificate->serial_no}}<br>Issued: {{$certificate->issued_on->format('d M Y')}}</p>@endif</div></body></html>
